Here's a custom React hook for handling window resize:

```javascript
import { useState, useEffect } from 'react';

function useWindowSize() {
    const [windowSize, setWindowSize] = useState({
        width: window.innerWidth,
        height: window.innerHeight,
    });

    useEffect(() => {
        let timeoutId = null;

        const handleResize = () => {
            // Debounce: wait 150ms after last resize event
            if (timeoutId) clearTimeout(timeoutId);
            timeoutId = setTimeout(() => {
                setWindowSize({
                    width: window.innerWidth,
                    height: window.innerHeight,
                });
            }, 150);
        };

        window.addEventListener('resize', handleResize);

        // Cleanup on unmount
        return () => {
            if (timeoutId) clearTimeout(timeoutId);
            window.removeEventListener('resize', handleResize);
        };
    }, []);

    return windowSize;
}

export default useWindowSize;

// Usage:
// function MyComponent() {
//     const { width, height } = useWindowSize();
//     const isMobile = width < 768;
//     return <div>{isMobile ? 'Mobile View' : 'Desktop View'}</div>;
// }
```

This hook returns the current window dimensions and updates when the window is resized. It includes debouncing (150ms delay) to avoid excessive re-renders during continuous resizing. The cleanup function removes the event listener when the component unmounts, preventing memory leaks. For responsive designs, you can combine this with CSS media queries for best performance.
